  const state={started:false,extracted:false,messages:[],draft:'',files:[],type:'',audience:'待补充',scenario:'待补充',goal:'待补充',core:'待补充',length:'待补充',other:'待补充',evidence:'待补充',channel:'待补充',stage:'需求理解',workflowStep:0,outlineChat:[],articleChat:[],documentHtml:'',modalRefs:[],activeOutlineIndex:0,dragOutlineIndex:null,outline:[{title:'会议背景与核心议题',description:'介绍会议缘起、专家信息及本次讨论的临床背景。',images:[{name:'会议议程与专家介绍',source:'专家课件 · 第2页'}],refs:['ref-1']},{title:'规范化检查的关键环节',description:'梳理标准流程、图像采集要求与质量控制重点。',images:[{name:'标准化检查流程图',source:'专家课件 · 第12页'}],refs:['ref-1','ref-2']},{title:'临床实践中的判断与应对',description:'结合专家案例说明不同临床情境下的实践要点。',images:[],refs:['ref-2']},{title:'总结与实践建议',description:'归纳会议共识，形成可执行的临床实践建议。',images:[],refs:[]}],referenceModal:false,query:'',filter:'全部',activeArticle:'ref-1',selectedRefs:[],references:[{id:'ref-1',title:'超声医学检查技术规范（2024版）',source:'中华医学会超声医学分会',type:'指南/规范',year:'2024',status:'全文可读',abstract:'围绕超声医学检查的标准化流程、图像采集与质量控制提出规范建议。适用于超声检查相关临床与技术人员。',content:'本规范旨在提升超声医学检查质量与结果一致性。\n\n一、检查前准备：根据检查目的确认适应证、患者信息及设备状态。\n\n二、图像采集：按照标准切面与操作流程完成检查，记录必要图像和测量信息。\n\n三、质量控制：定期开展图像质量评估，发现流程偏差并持续改进。\n\n文献来源：中华医学会超声医学分会，2024。'}, {id:'ref-2',title:'超声检查质量控制专家共识',source:'中国医师协会超声医师分会',type:'专家共识',year:'2023',status:'全文可读',abstract:'总结超声检查质量管理、人员培训和报告规范的专家建议。',content:'专家共识强调建立覆盖检查全流程的质量管理体系。\n\n一、人员培训：持续提升操作者规范化检查能力。\n\n二、过程管理：明确检查、图像留存及报告审核要求。\n\n三、持续改进：结合质量指标与临床反馈优化工作流程。\n\n文献来源：中国医师协会超声医师分会，2023。'}, {id:'ref-3',title:'临床超声检查流程优化的多中心研究',source:'中华超声影像学杂志',type:'临床研究',year:'2022',status:'仅摘要',abstract:'多中心观察研究评估流程优化与检查完整性之间的关系。当前仅可查看摘要，AI不会将其视为已阅读全文。',content:'摘要：研究纳入多家医疗机构，观察标准化流程实施前后的检查质量指标变化。结果提示流程管理与检查完整性相关。\n\n提示：当前仅有摘要，全文尚未获取；如需引用具体方法或数据，请补充全文。\n\n文献来源：中华超声影像学杂志，2022。'}]};
  const lfVeeva={page:1,submitted:false,form:{type:'Component Asset',subtype:'',classification:'',name:'bayer',therapeuticArea:'',product:'曼月乐',indication:'',country:'China',audience:['Consumer'],crmProduct:'',branding:'Branded',language:'Chinese (Simplified)',medicalType:'',distributionMode:'',publishClm:'No',publishRemoteClm:'No',publishWebLink:'No',approvalStart:'2026-10-27',materialOwner:'小李',medicalReviewer:'',medicalReviewerMode:'Every User',regulatoryReviewer:'',legalReviewer:'',otherReviewer:'',dueDate:'2026-11-10',distributionGroup:'',expiration:'24 months'}};
  const lfVeevaLabels={type:'类型（Type）',subtype:'子类型（Subtype）',classification:'分类（Classification）',name:'名称（Name）',therapeuticArea:'治疗领域（Therapeutic Area）',product:'产品（Product）',indication:'适应症（Indication）',country:'国家（Country）',audience:'受众（Audience）',crmProduct:'CRM 产品（CRM Product）',branding:'品牌属性（Branding）',language:'语言（Language）',medicalType:'医学类型（Medical Type）',distributionMode:'分发方式（Distribution Mode）',publishClm:'发布至 Veeva CRM（CLM）',publishRemoteClm:'发布至 Veeva CRM（Remote CLM）',publishWebLink:'发布至 Veeva CRM（Web Link）',approvalStart:'审批周期开始日期（Approval Cycle Start Date）',materialOwner:'材料负责人（Material Owner）',medicalReviewer:'医学审核人/批准人（Medical Reviewers/Approvers）',regulatoryReviewer:'法规审核人/批准人（Regulatory Reviewers/Approvers）',legalReviewer:'法务审核人/批准人（Legal Reviewers/Approvers）',otherReviewer:'其他审核人/批准人（Other Reviewers/Approvers）',dueDate:'审核/批准截止日期（Review/Approval Due Date）',distributionGroup:'分发组（Distribution Group）',expiration:'到期时长（Duration Until Expiration）'};
  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const initialDocument=()=>`<h1>从规范到实践：超声诊疗质量提升的关键路径</h1><p>在近期举行的专家研讨会上，多位临床专家围绕规范化检查、临床判断及质量控制展开了深入讨论。本文结合会议观点与参考资料，梳理超声诊疗质量提升的关键实践。</p><h2>规范化检查是诊断质量的基础</h2><p>专家指出，完整、连续的检查流程有助于减少信息遗漏，为后续临床判断提供可靠基础。检查前应明确检查目的，并根据规范完成图像采集和必要记录。</p>${state.outline[0]?.images?.[0]?`<figure><div class=\"lf-doc-image-placeholder\">▧</div><figcaption>${esc(state.outline[0].images[0].name)} · ${esc(state.outline[0].images[0].source)}</figcaption></figure>`:''}<h2>从标准流程走向个体化判断</h2><p>规范并不意味着机械执行。面对不同临床情况，应结合患者背景和影像表现进行综合判断，并在规范框架内回应实际诊疗需求。</p><h2>总结与实践建议</h2><p>将规范化流程落实到检查准备、图像采集和质量控制中，有助于持续提升诊疗质量。以上内容依据会议材料及已确认参考文献整理。</p><p class=\"lf-doc-citation\">参考资料：${state.selectedRefs.map(id=>state.references.find(r=>r.id===id)?.title).filter(Boolean).map(esc).join('；')||'待补充'}</p>`;
  if(!state.documentHtml)state.documentHtml=initialDocument();
  function enhance(){const tile=[...document.querySelectorAll('.workbench-tile')].find(x=>x.querySelector('h2')?.textContent.trim()==='医学与推广内容');if(!tile||tile.dataset.longformReady==='1')return;tile.dataset.longformReady='1';tile.classList.add('medical-tile');tile.dataset.longformEntry='1';tile.querySelector('p').textContent='从医学素材与传播目标出发，生成可追溯、可审核的长图文及配套运营内容。';tile.querySelector('.workbench-tags').innerHTML='<span>长图文</span><span>互动题</span><span>社群文案</span>';if(!tile.querySelector('.workbench-launch'))tile.insertAdjacentHTML('beforeend','<button class="workbench-launch" data-longform-open>进入长图文生成　→</button>')}
  function typeChoices(){return ['专家会议简报','FAQ／指南问答','互动性推文'].map((x,i)=>`<button class="lf-type ${state.type===x?'selected':''}" data-lf-type="${x}"><b>${x}</b><span>${['录音、课件和文献，整理专家观点','AI检索指南文献并生成有依据内容','提炼课程价值并生成配套运营材料'][i]}</span></button>`).join('')}
  function card(){const fields=[['受众','audience',true],['场景','scenario',true],['内容目标','goal',true],['核心信息','core',true],['篇幅','length',true],['其他','other',false],['叙事逻辑梗概','evidence',false]];return `<section class="lf-requirement-card"><div class="lf-card-head"><div><b>推文需求</b><span>${state.extracted?'AI 已从你的描述中提取':'等待你描述需求'}</span></div><button data-lf-edit>编辑</button></div><div class="lf-card-grid">${fields.map(([label,key,required])=>`<label class="lf-card-field ${state[key]==='待补充'?'missing':''} ${required?'required':''}"><small>${label}${required?'<em>*</em>':''}</small><textarea data-lf-field="${key}" placeholder="请输入${label}">${state[key]==='待补充'?'':esc(state[key])}</textarea>${state[key]==='待补充'?'<span class="lf-pending">待补充</span>':''}</label>`).join('')}</div><div class="lf-card-note">带 * 为必填项，AI会从你的描述中提取，未提及的内容请补充。</div></section>`}
  function prompt(){if(!state.extracted)return `<div class="lf-welcome"><div class="lf-welcome-icon">✦</div><h2>你想生成什么推文？</h2><p>可以直接描述主题、受众和用途，也可以选择推文类型或上传相关材料。</p><div class="lf-type-grid">${typeChoices()}</div></div>`;const missing=[['受众','audience'],['场景','scenario'],['内容目标','goal'],['核心信息','core'],['篇幅','length']].filter(([,k])=>state[k]==='待补充').map(([name])=>name);return `<div class="lf-followup"><div class="lf-ai-avatar">✦</div><div><b>我已整理你的需求</b><p>${state.type?`当前为「${state.type}」。`:''}${missing.length?`还缺少必填信息：<strong>${missing.join('、')}</strong>。你可以在右侧需求卡补充，也可以直接回复我。`:'必填信息已齐全，可以继续生成内容方案。'}</p></div></div>`}
  function messageReferences(ids=[]){return ids.length?`<div class="lf-message-refs">${ids.map(id=>{const r=state.references.find(x=>x.id===id);if(!r)return '';const selected=state.selectedRefs.includes(id);return `<article><div><b>${esc(r.title)}</b><small>${esc(r.source)} · ${esc(r.year)} · ${esc(r.status)}</small></div><button data-faq-view="${id}">查看原文</button><button class="${selected?'selected':''}" data-faq-select="${id}">${selected?'✓ 已加入':'＋ 加入本次任务'}</button></article>`}).join('')}</div>`:''}
  function mediaActions(m){if(!m.media)return '';const name=esc(m.media.name);if(m.media.kind==='audio')return `<section class="lf-media-action"><header><span>音</span><div><b>${name}</b><small>临时文件 · 不保存至素材库</small></div></header><p>输出的转写稿将保存至“我的素材库”，并自动加入本次任务材料。</p><footer><button class="primary" data-media-transcribe="${name}">开始转写</button><button data-media-dismiss>暂不处理</button></footer></section>`;return `<section class="lf-media-action"><header><span>视</span><div><b>${name}</b><small>临时文件 · 页面关闭后需重新上传</small></div></header><p>请先提取课件内容，再用于生成推文。视频原文件不会保存至素材库。</p><footer><button class="primary" data-media-video-ppt>转换为 PPT</button><button data-media-video-text="${name}">提取字幕／转写稿</button><button data-media-dismiss>暂不处理</button></footer></section>`}
  function messages(){return state.messages.map(m=>{const collected=m.turnId&&faq?.items?.some(item=>item.id===m.turnId);return `<div class="lf-message ${m.role}"><div class="lf-message-avatar">${m.role==='ai'?'✦ AI':'你'}</div><section class="lf-message-body"><p>${esc(m.text)}</p>${mediaActions(m)}${m.refs?.length?messageReferences(m.refs):''}${m.turnId?`<button class="lf-message-point ${collected?'added':''}" data-faq-collect="${m.turnId}" ${collected?'disabled':''}>${collected?'✓ 已加入推文要点':'＋ 推文要点'}</button>`:''}</section></div>`}).join('')}
  const chatReferenceBatches=[];
  const modelChoices=[['Default','Recommended set of models'],['6.1 Sol',''],['6 Astra',''],['6 Sol',''],['6 Luna',''],['5.6 Sol',''],['5.6 Terra',''],['5.6 Luna',''],['5.5','']];
  let selectedModel='Default',modelMenuOpen=false;
  function modelPicker(){return `<div class="lf-model-picker"><button data-model-toggle aria-expanded="${modelMenuOpen}"><span>${esc(selectedModel)}</span><i>⌄</i></button>${modelMenuOpen?`<div class="lf-model-menu"><header>Select model</header>${modelChoices.map(([name,note])=>`<button data-model-select="${esc(name)}"><span><b>${esc(name)}</b>${note?`<small>${esc(note)}</small>`:''}</span>${selectedModel===name?'<i>✓</i>':''}</button>`).join('')}</div>`:''}</div>`}
  function chatReferenceHistory(){return chatReferenceBatches.map((batch,index)=>`<section class="lf-chat-ref-batch"><header><div><span>✦ AI 检索</span><b>${esc(batch.query||'参考文章检索')}</b></div><small>${batch.ids.length} 篇 · 第 ${index+1} 次检索</small></header><div>${batch.ids.map(id=>{const r=state.references.find(x=>x.id===id);if(!r)return '';const selected=state.selectedRefs.includes(id);return `<article><div><b>${esc(r.title)}</b><small>${esc(r.source)} · ${esc(r.year)} · ${esc(r.status)}</small></div><button data-chat-ref-view="${id}">查看</button><button class="${selected?'selected':''}" data-chat-ref-toggle="${id}">${selected?'✓ 已加入本次任务':'＋ 加入本次任务'}</button></article>`}).join('')}</div></section>`).join('')}
  function referenceChips(){if(!state.selectedRefs.length)return '';return `<div class="lf-reference-chips"><b>本次参考文章</b>${state.selectedRefs.map(id=>{const r=state.references.find(x=>x.id===id);return r?`<span class="lf-ref-chip"><i>文</i><span><strong>${esc(r.title)}</strong><small>${esc(r.source)} · ${r.year} · ${r.status}</small></span><button data-lf-unselect="${r.id}" aria-label="移除${esc(r.title)}">×</button></span>`:''}).join('')}</div>`}
  function referenceModal(){if(!state.referenceModal)return '';const filtered=state.references.filter(r=>(state.filter==='全部'||r.type===state.filter)&&(!state.query||`${r.title} ${r.source} ${r.abstract}`.toLowerCase().includes(state.query.toLowerCase()))),article=state.references.find(r=>r.id===state.activeArticle)||filtered[0],chosen=state.modalRefs.length;return `<div class="lf-modal-backdrop" data-lf-backdrop><section class="lf-reference-modal" role="dialog" aria-modal="true" aria-label="搜索参考文章"><header><div><h2>搜索参考文章</h2><p>选择可供AI参考的文章。全文和摘要状态会明确标记。</p></div><button data-lf-close-modal aria-label="关闭">×</button></header><div class="lf-ref-search"><input data-lf-query value="${esc(state.query)}" placeholder="输入主题、文章类型或文献信息"><button data-lf-search>搜索文章</button></div><div class="lf-ref-filters">${['全部','指南/规范','专家共识','临床研究'].map(x=>`<button class="${state.filter===x?'active':''}" data-lf-filter="${x}">${x}</button>`).join('')}</div><div class="lf-ref-browser"><div class="lf-ref-results"><div class="lf-ref-results-head">检索结果 <span>${filtered.length} 篇</span></div>${filtered.map(r=>`<button class="lf-ref-result ${article?.id===r.id?'active':''}" data-lf-open-article="${r.id}"><span class="lf-ref-checkbox ${state.modalRefs.includes(r.id)?'checked':''}" data-lf-toggle="${r.id}">${state.modalRefs.includes(r.id)?'✓':''}</span><span class="lf-ref-result-copy"><b>${esc(r.title)}</b><small>${esc(r.source)} · ${r.type} · ${r.year}</small><em class="${r.status==='仅摘要'?'abstract':''}">${r.status}</em></span></button>`).join('')||'<p class="lf-ref-empty">没有匹配文章，请调整关键词。</p>'}</div><article class="lf-ref-detail">${article?`<div class="lf-ref-detail-meta"><span>${article.type}</span><span>${article.year}</span><span class="${article.status==='仅摘要'?'abstract':''}">${article.status}</span></div><h3>${esc(article.title)}</h3><p class="lf-ref-source">${esc(article.source)}</p><h4>${article.status==='全文可读'?'文章内容':'摘要内容'}</h4><div class="lf-ref-body">${esc(article.content)}</div><button class="lf-ref-select ${state.modalRefs.includes(article.id)?'selected':''}" data-lf-toggle="${article.id}">${state.modalRefs.includes(article.id)?'✓ 已选为参考文章':'＋ 选为参考文章'}</button>`:'<p class="lf-ref-empty">选择左侧文章查看内容。</p>'}</article></div><footer><span>已选 ${chosen} 篇文章</span><div><button class="lf-ref-cancel" data-lf-close-modal>取消</button><button class="lf-ref-confirm" data-lf-confirm-refs ${chosen?'':'disabled'}>添加到本次任务</button></div></footer></section></div>`}
  function contentPreview(){if(!state.extracted)return '';const ready=['audience','scenario','goal','core','length'].every(k=>state[k]!=='待补充'&&state[k].trim());return `<section class="lf-next-preview"><div><span class="pill pill-blue">下一步</span><b>确认需求后，AI将生成内容方案</b><p>包含标题方向、文章结构、素材使用范围，以及是否需要配图、互动题和社群文案。</p></div><button data-lf-generate ${ready?'':'disabled'}>生成内容方案 →</button></section>`}
  function visibleWorkflowSteps(){const steps=workflowSteps.map((name,id)=>({name,id}));if(isTraffic())steps.splice(3,0,{name:'课程亮点与互动题',id:6});return steps.filter(step=>step.id!==3||state.canvaSaved)}
  function stepper(){const steps=visibleWorkflowSteps(),active=steps.findIndex(step=>step.id===state.workflowStep);return `<nav class="lf-stepper" aria-label="推文生成进度">${steps.map(({name,id},index)=>`<button class="lf-step ${index===active?'active':index<active?'done':''}" data-lf-step="${id}" ${index>active?'disabled':''}><i>${index<active?'✓':index+1}</i><span>${name}</span></button>`).join('')}</nav>`}
  function chatPanel(kind){const items=kind==='outline'?state.outlineChat:state.articleChat;return `<aside class="lf-ai-panel"><div class="lf-ai-panel-head"><span class="lf-ai-avatar">✦</span><div><b>AI 内容助手</b><small>${kind==='outline'?'协助调整章节结构和素材':'协助修改文章内容'}</small></div></div><div class="lf-ai-panel-messages">${items.map(m=>`<div class="${m.role}">${esc(m.text)}</div>`).join('')||`<div class="ai">${kind==='outline'?'可以告诉我如何调整章节，例如“增加一节讨论临床实践挑战”。':'可以让我重写、扩写或精简内容；修改也可以直接在文档中完成。'}</div>`}</div><div class="lf-ai-panel-compose"><textarea data-lf-chat-input="${kind}" placeholder="${kind==='outline'?'描述你希望如何调整大纲…':'告诉我希望如何修改正文…'}"></textarea><button data-lf-chat-send="${kind}">发送</button></div></aside>`}
  function outlineStage(){
    const cards=state.outline.map((item,i)=>`<article class="lf-outline-section" draggable="true" data-lf-outline-card="${i}">
      <div class="lf-outline-section-head"><span class="lf-chapter-number">${i+1}</span><i class="lf-drag-handle" aria-label="拖拽排序" title="拖拽调整章节顺序">⠿</i><input data-lf-outline-title="${i}" value="${esc(item.title)}" aria-label="本章标题"><button data-lf-delete-section="${i}" aria-label="删除章节" title="删除章节">×</button></div>
      <label class="lf-outline-field"><small>本章核心内容</small><textarea data-lf-outline-description="${i}" aria-label="章节核心内容">${esc(item.description)}</textarea></label>
      <section class="lf-outline-assets lf-chapter-images"><div class="lf-assets-heading"><b>引用图片</b></div><div class="lf-image-grid">${item.images.map((img,j)=>`<figure class="lf-outline-image"><div class="lf-outline-thumbnail">${img.url?`<img src="${esc(img.url)}" alt="${esc(img.name)}">`:''}<span>${j+1}</span><button data-lf-delete-image="${i}:${j}" aria-label="移除图片" title="移除图片">×</button></div><figcaption>${esc(img.name)}<sup>${j+1}</sup><small>来源：${esc(img.source)}</small>${img.literature?`<small>文献：${esc(img.literature)}</small>`:''}</figcaption></figure>`).join('')}<label class="lf-image-add" title="上传图片" aria-label="上传图片"><span aria-hidden="true">＋</span><input type="file" accept="image/*" data-lf-image="${i}" hidden></label></div></section>
      <section class="lf-outline-assets"><div class="lf-assets-heading"><b>参考文献</b><button data-lf-open-refs="${i}">＋ 添加文献</button></div>${item.refs.length?item.refs.map(id=>{const r=state.references.find(x=>x.id===id);return r?`<div class="lf-asset-row"><i>文</i><span><b>${esc(r.title)}</b><small>${esc(r.source)} · ${r.year} · ${r.status}</small></span><button data-lf-unselect-chapter="${i}:${r.id}">移除</button></div>`:''}).join(''):'<p>本章暂未引用文献</p>'}</section>
    </article><div class="lf-outline-insert"><span></span><button data-lf-insert-section="${i+1}" aria-label="在此处添加章节">＋</button></div>`).join('');
    return `<div class="lf-stage-heading"><div><h2>生成推文大纲</h2><p>每章独立管理标题、核心内容、配图和参考文献；拖动章节卡片可调整顺序。</p></div></div><div class="lf-outline-layout"><section class="lf-outline-editor">${cards}${state.outline.length?'':'<div class="lf-outline-insert"><span></span><button data-lf-insert-section="0" aria-label="添加章节">＋</button></div>'}</section>${chatPanel('outline')}</div><footer class="lf-stage-footer"><button class="lf-plain" data-lf-back>← 返回对话</button><button class="lf-primary" data-lf-to-article>确认大纲并生成推文内容 →</button></footer>`
  }
  function articleStage(){return `<div class="lf-stage-heading"><div><h2>生成推文内容</h2><p>可直接编辑文档，也可以通过右侧AI助手提出修改要求。</p></div><span class="lf-doc-status">● 自动保存</span></div><div class="lf-word-layout"><section class="lf-word"><div class="lf-word-ribbon"><div class="lf-word-tools"><select aria-label="字体"><option>微软雅黑</option><option>宋体</option><option>黑体</option></select><select data-lf-font-size aria-label="字号"><option value="3">小四</option><option value="4" selected>14</option><option value="5">16</option><option value="6">18</option><option value="7">24</option></select><button data-lf-format="bold"><b>B</b></button><button data-lf-format="italic"><i>I</i></button><button data-lf-format="underline"><u>U</u></button><span></span><button data-lf-format="insertUnorderedList">• 列表</button><button data-lf-format="justifyLeft">左对齐</button><button data-lf-format="justifyCenter">居中</button><label class="lf-inline-upload">▧ 插入图片<input type="file" accept="image/*" data-lf-doc-image hidden></label><button data-lf-doc-image-from-assets>从素材插入</button></div></div><article class="lf-word-page" contenteditable="true" data-lf-document>${state.documentHtml||initialDocument()}</article></section>${chatPanel('article')}</div><footer class="lf-stage-footer"><button class="lf-plain" data-lf-back>← 返回大纲</button><button class="lf-primary" data-lf-next-stage="3">确认内容并继续 →</button></footer>`}
  function laterStage(){const names={3:'排版样式',4:'意见收集',5:'提交 Veeva 审批'};return `<div class="lf-stage-heading"><div><h2>${names[state.workflowStep]}</h2><p>${state.workflowStep===3?'调整推文的图文呈现和发布样式。':state.workflowStep===4?'收集并处理相关审核意见。':'完成Veeva审批信息并提交。'}</p></div></div><section class="lf-later-panel"><div class="lf-later-mark">${state.workflowStep===3?'▤':state.workflowStep===4?'✎':'✓'}</div><h3>${state.workflowStep===3?'图文排版预览':state.workflowStep===4?'意见与修改':'Veeva审批提交'}</h3><p>${state.workflowStep===3?'预览长图文中的标题、正文、图片及图注布局。':state.workflowStep===4?'展示待处理意见，并在修改后重新提交确认。':'填写审批元数据并将内容提交至Veeva。'}</p>${state.workflowStep===3?'<button class="lf-primary" data-lf-next-stage="4">提交排版确认 →</button>':state.workflowStep===4?'<button class="lf-primary" data-lf-next-stage="5">进入Veeva审批 →</button>':'<button class="lf-primary" data-lf-finish>提交审批</button>'}</section><footer class="lf-stage-footer"><button class="lf-plain" data-lf-back>← 上一步</button></footer>`}
  function lfVeevaField(key,control,required=false){return `<div class="field"><label>${lfVeevaLabels[key]}${required?' *':''}</label>${control}</div>`}
  function lfVeevaInput(key,required=false,type='text',placeholder=''){return lfVeevaField(key,`<input class="input" type="${type}" data-lf-veeva-field="${key}" value="${esc(lfVeeva.form[key]||'')}" placeholder="${esc(placeholder)}">`,required)}
  function lfVeevaSelect(key,values,required=false,multiple=false){const value=lfVeeva.form[key];return lfVeevaField(key,`<select class="select" data-lf-veeva-field="${key}" ${multiple?'multiple':''}>${values.map(item=>`<option value="${esc(item)}" ${Array.isArray(value)?value.includes(item)?'selected':'':value===item?'selected':''}>${esc(item)}</option>`).join('')}</select>${multiple?'<span class="field-hint">可多选</span>':''}`,required)}
  function lfVeevaPage(){const v=lfVeeva.form,types=['Content Module','Approval Not Needed Content','Claim','Component Asset','Corporate','Customer Consent','Email Fragment','Email Template','Event Material','Health Authority Form','License Files','Market Access (Approval Needed)','Market Research (Approval Needed)','Material','Medical','Tracking Module','Module Map','Multichannel Slide','Reference','Template Fragment'],audiences=['Advisory Board','Caregivers','Consumer','Government','Health Administrator','Internal','Journalist / Media (Press)','Midwives','Nurses','Others','Patient / Consumer','Patient Organization','Payer','Pharmacists','Physicians','Radiologists','Sales Force'];const general=`<div class="form-grid">${lfVeevaSelect('type',types,true)}${lfVeevaInput('subtype')}${lfVeevaInput('classification')}${lfVeevaInput('name',true)}${lfVeevaInput('therapeuticArea',true)}${lfVeevaInput('product',true)}${lfVeevaInput('indication',true)}${lfVeevaInput('country',true)}${lfVeevaSelect('audience',audiences,true,true)}${lfVeevaInput('crmProduct',true)}${lfVeevaSelect('branding',['Branded','Unbranded'],true)}${lfVeevaSelect('language',['Chinese (Simplified)'],true)}${lfVeevaInput('medicalType',true)}${lfVeevaInput('distributionMode',true)}${lfVeevaSelect('publishClm',['Yes','No'],true)}${lfVeevaSelect('publishRemoteClm',['Yes','No'],true)}${lfVeevaSelect('publishWebLink',['Yes','No'],true)}${lfVeevaInput('approvalStart',true,'date')}</div>`;const reviewFields=`<div class="form-grid">${lfVeevaInput('materialOwner',true,'text','输入 CWID 或邮箱搜索')}${lfVeevaField('medicalReviewer',`<div class="reviewer-modes"><label><input type="radio" name="lfMedicalReviewerMode" value="Every User" data-lf-veeva-field="medicalReviewerMode" ${v.medicalReviewerMode==='Every User'?'checked':''}> 每位用户（Every User）</label><label><input type="radio" name="lfMedicalReviewerMode" value="Any User" data-lf-veeva-field="medicalReviewerMode" ${v.medicalReviewerMode==='Any User'?'checked':''}> 任一用户（Any User）</label></div><input class="input" data-lf-veeva-field="medicalReviewer" value="${esc(v.medicalReviewer||'')}" placeholder="输入 CWID 或邮箱搜索">`,true)}${lfVeevaInput('regulatoryReviewer')}${lfVeevaInput('legalReviewer')}${lfVeevaInput('otherReviewer')}${lfVeevaInput('dueDate',true,'date')}${lfVeevaInput('crmProduct',true)}${lfVeevaInput('distributionGroup',true)}${lfVeevaSelect('expiration',['10 months','12 months','24 months'],true)}</div>`;return `<section class="veeva-submit lf-veeva-submit"><div class="veeva-gate"><span class="pill pill-green">✓ 小王已内部确认</span><b>123</b></div><div class="veeva-substeps"><span class="${lfVeeva.page===1?'active':''}">1 · 材料信息</span><i></i><span class="${lfVeeva.page===2?'active':''}">2 · 审核配置</span></div>${lfVeeva.page===1?`<section class="card veeva-form-card"><div class="section-title">材料类型、General 信息与 CLM 属性</div>${general}<div class="page-actions"><button class="btn btn-quiet" data-lf-veeva-feedback>← 返回意见收集</button><button class="btn btn-primary" data-lf-veeva-next>下一步：审核配置 →</button></div></section>`:`<section class="card veeva-form-card"><div class="section-title">开始审核/批准（Start Review/Approval）</div><p class="field-hint">配置材料负责人、审核人和审批期限。</p>${reviewFields}<div class="page-actions"><button class="btn btn-quiet" data-lf-veeva-back>← 上一步</button><button class="btn btn-primary" data-lf-veeva-submit>提交 VEEVA 审批</button></div></section>`}${lfVeeva.submitted?'<div class="lf-veeva-success">✓ 已模拟提交 VEEVA 审批申请，等待审批。</div>':''}</section>`}
  function workflowPage(){return `<div class="lf-app"><header class="lf-top"><div class="lf-brand"><button data-lf-home aria-label="返回工作台">←</button><span class="workbench-logo">✦</span><div><b>Bavidea</b><small>医学与推广内容 · AI 推文生成</small></div></div><div class="lf-top-meta"><span>● 已自动保存</span><button>帮助</button></div></header><main class="lf-main"><div class="lf-heading"><div><span class="heading-eyebrow">AI CONTENT STUDIO</span><h1>自由生成医学与推广推文</h1><p>${state.type||'新建推文'} · ${state.audience}</p></div><span class="pill pill-green">${visibleWorkflowSteps().find(x=>x.id===state.workflowStep)?.name||''}</span></div>${stepper()}${state.workflowStep===1?outlineStage():state.workflowStep===2?articleStage():state.workflowStep===5?lfVeevaPage():state.workflowStep===6?trafficExtrasStage():laterStage()}</main>${referenceModal()}</div>`}
  function render(){root().innerHTML=state.workflowStep>0?workflowPage():`<div class="lf-app"><header class="lf-top"><div class="lf-brand"><button data-lf-home aria-label="返回工作台">←</button><span class="workbench-logo">✦</span><div><b>Bavidea</b><small>医学与推广内容 · AI 推文生成</small></div></div><div class="lf-top-meta"><span>● 已自动保存</span><button>帮助</button></div></header><main class="lf-main"><div class="lf-heading"><div><span class="heading-eyebrow">AI CONTENT STUDIO</span><h1>自由生成医学与推广推文</h1><p>用自然语言描述你的需求，AI 会提取关键信息并主动补齐缺项。</p></div><span class="pill ${state.extracted?'pill-green':'pill-blue'}">${state.stage}</span></div>${stepper()}<div class="lf-workspace"><section class="lf-conversation"><div class="lf-thread">${messages()}${prompt()}${state.type==='专家会议简报'?`<div class="lf-thread-reference">${referenceChips()}</div>`:''}${contentPreview()}</div><div class="lf-composer"><div class="lf-composer-tools"><button class="lf-preprocess" data-library-plugins>素材预处理</button></div><div class="lf-attach-list">${state.files.map(f=>`<span>▧ ${esc(f)}</span>`).join('')}</div><textarea data-lf-input placeholder="例如：根据专家会议录音和PPT，面向影像科医生，在科室培训场景下介绍规范化检查要点，约1500字…">${esc(state.draft)}</textarea><div class="lf-compose-foot"><label class="lf-upload-btn">＋ 添加材料<input type="file" multiple data-lf-file hidden></label><span>支持录音、转写稿、PPT、PDF、Word、文献和Demo</span>${modelPicker()}<button class="lf-send" data-lf-send>发送　→</button></div></div></section><aside class="lf-context"><h3>需求信息</h3>${card()}<section class="lf-materials"><div class="lf-side-head"><b>已添加材料</b><span>${state.files.length+state.selectedRefs.length?state.files.length+state.selectedRefs.length+' 个':'暂无'}</span></div>${state.selectedRefs.map(id=>{const r=state.references.find(x=>x.id===id);return r?`<div class="lf-material"><i>文</i><div><b>${esc(r.title)}</b><small>${r.year} · ${r.status}</small></div><button data-lf-unselect="${r.id}">×</button></div>`:''}).join('')}${state.files.map((f,i)=>`<div class="lf-material"><i>${i===0?'音':i===1?'P':'文'}</i><div><b>${esc(f)}</b><small>等待AI解析</small></div><button data-lf-remove="${i}">×</button></div>`).join('')}${!state.files.length&&!state.selectedRefs.length?'<p>上传材料后，AI会自动识别内容、页码和引用关系。</p>':''}</section><section class="lf-status"><b>生成状态</b><div><span class="lf-status-dot"></span>${state.extracted?'需求已识别，等待确认':'等待输入需求'}</div></section></aside></div></main>${referenceModal()}</div>`;if(state.workflowStep===0){const workspace=document.querySelector('.lf-workspace');workspace.classList.add('lf-chat-workspace');document.querySelector('.lf-app').classList.add('lf-chat-page');const context=workspace.querySelector('.lf-context');context.querySelector('h3').textContent='本次任务材料';context.querySelector('.lf-requirement-card')?.remove();context.querySelector('.lf-status')?.remove();workspace.querySelector('.lf-attach-list').innerHTML='';const opening=state.type?'你想生成一篇什么样的'+esc(state.type)+'？可以先描述需求，也可以上传相关材料。':'';workspace.querySelector('.lf-thread').innerHTML=(state.type?'<div class="lf-message ai"><div>✦ AI</div><p>'+opening+'</p></div>':prompt())+messages()+chatReferenceHistory()+conversationSummary();const thread=workspace.querySelector('.lf-thread');if(state.messages.length)thread.scrollTop=thread.scrollHeight;}}
  function extract(text){const t=text.toLowerCase();if(/faq|指南|问答|临床问题/.test(t))state.type='FAQ／指南问答';else if(/课程|视频|引流|社群/.test(t))state.type='互动性推文';else if(/专家|会议|简报|录音|课件|ppt/.test(t))state.type='专家会议简报';const audience=(text.match(/(?:面向|受众是?|目标读者是?)([^，。；;]+)/)||[])[1];if(audience)state.audience=audience;const scenario=(text.match(/(?:场景是?|用于|在)([^，。；;]*(?:场景|培训|会议|门诊|病房|科室|术前|术后)[^，。；;]*)/)||[])[1];if(scenario)state.scenario=scenario;if(/公众号|网站|微信群|社群|小红书/.test(t))state.channel=(text.match(/公众号|网站|微信群|社群|小红书/)||[])[0]||state.channel;const target=(text.match(/(?:内容目标是?|目标是|目的是|旨在|用于)([^，。；;]+)/)||[])[1];if(target)state.goal=target;else if(text.includes('引流'))state.goal='课程引流';else if(text.includes('回答'))state.goal='回答临床问题';const core=(text.match(/(?:核心信息是?|核心信息包括|重点是|核心是)([^。；;]+)/)||[])[1];if(core)state.core=core;;const length=(text.match(/约?\s*\d+\s*(?:字|字左右|篇幅)/)||[])[0];if(length)state.length=length;if(/素材|文献|课件|录音/.test(t))state.evidence=state.type==='FAQ／指南问答'?'人工确认的指南、共识和研究':state.type==='互动性推文'?'仅使用课程材料':'上传材料为主，文献须确认'}
  const requiredFields=[['受众','audience'],['场景','scenario'],['内容目标','goal'],['核心信息','core'],['篇幅','length']];
  const missingFields=()=>requiredFields.filter(([,key])=>!state[key]?.trim()||state[key]==='待补充').map(([label])=>label);
  let pendingImage=null;
  const temporaryMedia=new Map();
  function isVideoFile(file){return !!file&&(String(file.type||'').startsWith('video/')||/\.(mp4|mov|avi|mkv|webm|m4v)$/i.test(file.name||''))}
  function imageSourceDialog(){
    document.querySelector('[data-lf-image-dialog]')?.remove();
    if(!pendingImage)return;
    root().insertAdjacentHTML('beforeend',`<div class="lf-modal-backdrop" data-lf-image-dialog><form class="lf-image-source-dialog" role="dialog" aria-modal="true" aria-labelledby="lf-image-source-title"><header><h2 id="lf-image-source-title">补充图片来源</h2><button type="button" data-lf-cancel-image aria-label="关闭">×</button></header><div class="lf-image-source-preview"><img src="${esc(pendingImage.url)}" alt="${esc(pendingImage.name)}"><span>${esc(pendingImage.name)}</span></div><label>图片来源 <em>*</em><input name="source" required placeholder="例如：专家课件第12页 / 原文图2"></label><label>参考文献 <em>*</em><textarea name="literature" required placeholder="请输入文献标题、作者、年份或 DOI"></textarea></label><footer><button type="button" class="lf-plain" data-lf-cancel-image>取消</button><button type="submit" class="lf-primary">确认添加</button></footer></form></div>`);
    document.querySelector('.lf-image-source-dialog input')?.focus();
  }
  document.addEventListener('click',e=>{if(!e.target.closest('[data-lf-cancel-image]'))return;if(pendingImage)URL.revokeObjectURL(pendingImage.url);pendingImage=null;document.querySelector('[data-lf-image-dialog]')?.remove()});
  document.addEventListener('submit',e=>{
    if(!e.target.matches('.lf-image-source-dialog'))return;
    e.preventDefault();if(!pendingImage)return;
    const source=e.target.elements.source,literature=e.target.elements.literature;
    for(const field of [source,literature]){field.setCustomValidity(field.value.trim()?'':'请填写此项');if(!field.reportValidity())return;}
    state.outline[pendingImage.chapter].images.push({name:pendingImage.name,url:pendingImage.url,source:source.value.trim(),literature:literature.value.trim()});
    pendingImage=null;render();
  });
  document.addEventListener('input',e=>{if(e.target.closest('.lf-image-source-dialog'))e.target.setCustomValidity?.('')});
  let pendingQuestion=null;
  function analyzeRequirements(text){
    const previousType=state.type;
    if(!previousType){if(/FAQ|指南问答|问答/i.test(text))state.type='FAQ／指南问答';else if(/视频|课程|互动/.test(text))state.type='互动性推文';else if(/会议|简报/.test(text))state.type='专家会议简报';}
    const patterns={
      audience:/(?:面向|受众(?:是|为)?|目标读者(?:是|为)?|写给)\s*[:：]?\s*([^，。；;\n]+)/,
      scenario:/(?:场景(?:是|为)?\s*[:：]?\s*|(?:发(?:布)?(?:在|到)?|用于|用在|在))([^，。；;\n]*(?:公众号|网站|社群|微信群|科室培训|培训|门诊|病房)[^，。；;\n]*)/,
      goal:/(?:内容目标(?:是|为)?|目标(?:是|为)?|目的是|旨在|希望(?:读者|医生)?(?:看完后)?|帮助(?:读者|医生))\s*[:：]?\s*([^，。；;\n]+)/,
      core:/(?:核心信息(?:是|为|包括)?|重点(?:是|讲|介绍|介绍的是)?|核心(?:是|内容)?|主要(?:讲|介绍)|主题(?:是|为)?)\s*[:：]?\s*([^，。；;\n]+)/,
      length:/(?:约|大约)?\s*\d+\s*(?:[-～至到]\s*\d+\s*)?字(?:左右)?/
    };
    const changed=[];
    for(const [key,pattern] of Object.entries(patterns)){
      const match=text.match(pattern);if(!match)continue;
      let value=(match[1]||match[0]).trim();
      if(key==='audience')value=value.replace(/的?(?:专家)?会议简报.*$/,'').trim();
      if(value){state[key]=value;changed.push(key);}
    }
    for(const [label,key] of [...requiredFields,['叙事逻辑梗概','evidence']]){
      const match=text.match(new RegExp(label+'(?:改为|改成|调整为|是|为|：|:)[ \\t]*([^，。；;\\n]+)'));
      if(match){state[key]=match[1].trim();changed.push(key);}
    }
    return changed;
  }
  function conversationSummary(){
    if(!state.extracted||missingFields().length)return '';
    const refs=state.selectedRefs.map(id=>state.references.find(ref=>ref.id===id)).filter(Boolean);
    const materials=(state.files.length?`<div class="lf-summary-materials"><dt>已上传文件 · ${state.files.length}</dt><dd><ul>${state.files.map(file=>`<li>${esc(file)}</li>`).join('')}</ul></dd></div>`:'')+(refs.length?`<div class="lf-summary-materials"><dt>已选参考文献 · ${refs.length}</dt><dd><ul>${refs.map(ref=>`<li><strong>${esc(ref.title)}</strong><small>${esc(ref.source)} · ${esc(ref.year)} · ${esc(ref.status)}</small></li>`).join('')}</ul></dd></div>`:'');
    return `<section class="lf-chat-summary"><header><div><span class="lf-summary-eyebrow">实时需求摘要</span><h3>${esc(state.type||'推文')} · 当前版本</h3></div><span class="lf-summary-ready">已随对话更新</span></header><dl>${requiredFields.map(([label,key])=>`<div class="lf-summary-${key}"><dt>${label}</dt><dd>${esc(state[key])}</dd></div>`).join('')}${materials}</dl><footer><p>可以继续对话、检索或调整本次材料；生成时以这里的最新状态为准。</p><button class="lf-primary" data-lf-generate>根据当前需求与材料生成大纲 →</button></footer></section>`;
  }
  function followupQuestion(){
    const missing=requiredFields.filter(([,key])=>state[key]==='待补充'||!state[key]?.trim());
    pendingQuestion=missing.length===1?missing[0][1]:null;
    const questions={audience:'这篇推文主要写给谁看？例如影像科医生、基层医生或患者。',scenario:'这篇推文准备在哪个场景使用？例如公众号发布或科室培训。',goal:'你希望读者看完后有什么收获，或采取什么行动？',core:'这篇推文必须传达哪些核心观点或会议信息？',length:'希望推文大约多少字？例如800字、1500字或2000字。'};
    if(!missing.length)return '五项关键信息已齐全，请确认下方需求摘要。需要调整的话，直接告诉我即可。';
    const known=requiredFields.filter(([,key])=>state[key]!=='待补充'&&state[key]?.trim()).map(([label,key])=>`${label}：${state[key]}`);
    return (known.length?'已记录：'+known.join('；')+'。\n\n':'')+'还需要你补充以下信息，可以一次性回复：\n'+missing.map(([label,key],i)=>`${i+1}. ${label}：${questions[key]}`).join('\n');
  }
  function expertForm(){
    const fields=[...requiredFields,['叙事逻辑梗概','evidence']];
    return `<section class="lf-expert-form"><h2>专家会议简报 · 推文需求</h2><div class="lf-expert-fields">${fields.map(([label,key])=>`<label class="lf-card-field"><small>${label}${key!=='evidence'?'<em> *</em>':'（选填）'}</small>${key==='length'?`<select data-lf-length-mode aria-label="篇幅"><option value="">请选择篇幅</option>${['800字','1500字','2000字','自定义'].map(v=>`<option ${v===(['800字','1500字','2000字'].includes(state.length)?state.length:state.length==='待补充'?'':'自定义')?'selected':''}>${v}</option>`).join('')}</select><input data-lf-field="length" aria-label="自定义篇幅" placeholder="例如：1200字" value="${state.length==='待补充'?'':esc(state.length)}">`:key==='core'||key==='evidence'?`<textarea data-lf-field="${key}" placeholder="${key==='evidence'?'例如：会议背景 → 专家观点 → 实践建议': '请输入'+label}">${state[key]==='待补充'?'':esc(state[key])}</textarea>`:`<input data-lf-field="${key}" placeholder="请输入${label}" value="${state[key]==='待补充'?'':esc(state[key])}">`}</label>`).join('')}</div><div class="lf-expert-materials"><button class="lf-upload-btn" data-lf-open-refs="">搜索参考文章</button><label class="lf-upload-btn">上传会议材料<input type="file" multiple data-lf-file hidden></label>${referenceChips()}${state.files.map((f,i)=>`<div class="lf-material"><i>文</i><div><b>${esc(f)}</b><small>会议材料</small></div><button data-lf-remove="${i}" aria-label="移除材料">×</button></div>`).join('')}</div><footer><span data-lf-required-status>${missingFields().length?'待补充：'+missingFields().join('、'):'必填信息已齐全'}</span><button class="lf-primary" data-lf-generate ${missingFields().length?'disabled':''}>确认需求，生成大纲</button></footer></section>`;
  }
  function send(){
    const input=document.querySelector('[data-lf-input]');
    const text=input?.value.trim();
    if(!text&&!state.files.length)return;
    if(text){
      state.messages.push({role:'user',text});state.draft='';
      const media=[...temporaryMedia.values()].at(-1);
      if(media&&isAudioFile(media)&&/(转|转换|生成|提取).{0,6}(文字|文本|字幕|转写)|录音.{0,6}(文字|转写)/.test(text)){state.messages.push({role:'ai',text:`已识别到你希望将“${media.name}”转为文字。确认后会临时上传并开始转写，原录音不会保存至素材库。`,media:{kind:'audio',name:media.name}});render();return}
      if(media&&isVideoFile(media)&&/(根据|使用|处理|分析|生成|提取|转换|转).{0,8}(视频|课件|字幕|文字|PPT|推文)|视频.{0,8}(推文|文字|字幕|PPT)/i.test(text)){state.messages.push({role:'ai',text:`已识别到你希望处理视频课件“${media.name}”。生成推文前需要先提取课件内容，请选择处理方式。`,media:{kind:'video',name:media.name}});render();return}
      if(isFaq()&&!faq.writing){state.messages.pop();state.draft=text;sendFaq();return}
      const before=Object.fromEntries(requiredFields.map(([,key])=>[key,state[key]]));
      const changed=analyzeRequirements(text);
      const explicit=changed.length>0;
      if(pendingQuestion&&!explicit&&!requiredFields.some(([,key])=>before[key]!==state[key])){
        if(/帮我建议|你来建议|你推荐/.test(text)){
          const suggestions={audience:'相关专科医生',scenario:'公众号发布',goal:'帮助读者理解会议观点与实践要点',core:'会议核心观点与临床实践建议',length:'1500字'};
          state.messages.push({role:'ai',text:'建议'+requiredFields.find(([,key])=>key===pendingQuestion)[0]+'为“'+suggestions[pendingQuestion]+'”。你同意吗？也可以直接告诉我你的选择。'});
          state.pendingSuggestion=suggestions[pendingQuestion];render();return;
        }
        if(state.pendingSuggestion&&/^(同意|可以|好的|确认|是的)[。！!]?$/u.test(text))state[pendingQuestion]=state.pendingSuggestion;
        else if(!/^(不知道|不确定|跳过|随便)$/.test(text))state[pendingQuestion]=text;
        state.pendingSuggestion=null;
      }
    }
    if(state.files.length&&!state.extracted)state.evidence='上传材料为主，文献须确认';
    state.extracted=true;
    state.stage='需求待确认';
    state.messages.push({role:'ai',text:followupQuestion()});
    render();
  }
