    const openRefs=e.target.closest('[data-lf-open-refs]');if(openRefs){state.activeOutlineIndex=openRefs.dataset.lfOpenRefs===''?null:Number(openRefs.dataset.lfOpenRefs);state.modalRefs=(state.activeOutlineIndex===null?state.selectedRefs:state.outline[state.activeOutlineIndex].refs).slice();state.referenceModal=true;render();return}
